<?php require_once __DIR__.'/includes/bootstrap.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$pass=$_POST['password']??'';$s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['role']=$u['role'];$_SESSION['full_name']=$u['full_name'];header('Location: index.php');exit;}$error='Incorrect email or password.';}$title='Login';require 'includes/header.php';?><section class="panel narrow"><h1>QueueLess Ghana</h1><p>Demo password: <b>Queue123!</b></p><?php if($error):?><p class="notice error"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" required></label><button>Sign in</button></form><p>Customer: customer@queueless.test<br>Business: owner@queueless.test</p></section><?php require 'includes/footer.php';?>